// This file covers a slice of the never-parity-recorded Describe/List
// operations (regenerated by grepping the dispatch table's own
// "OpName": h.handleOpName / ops["OpName"] = h.handleOpName registrations
// and subtracting names PARITY.md already mentions). It fixes eight
// previously-unread/misread-parameter bugs and confirms nine more operations
// read their wire keys correctly. Four further operations
// (DescribeTransitGatewayConnects/ConnectPeers/PeeringAttachments/
// RouteTables) were already fixed and covered by real-client tests in
// wire_field_fixes_ec2sweep36_test.go -- PARITY.md simply never recorded
// them; see PARITY.md for that correction.

// ---- Bug 1: DescribePrincipalIdFormat ----
//
// handleDescribePrincipalIDFormat used to read "PrincipalArn" -- a key that
// does not exist anywhere on DescribePrincipalIdFormatInput
// (api_op_DescribePrincipalIdFormat.go has no such field at all; the
// operation always describes the calling principal) -- and never read the
// real Resource.N filter the wire does declare
// (awsEc2query_serializeOpDocumentDescribePrincipalIdFormatInput: FlatKey
// "Resource"). A real client's Resources filter was silently dropped and
// every resource type's ID-format status came back regardless.
func TestDescribePrincipalIdFormat_ResourceFilter_RealClient(t *testing.T) {
	t.Parallel()

	h := ec2.NewHandler(ec2.NewInMemoryBackend("000000000000", "us-east-1"))
	client := newTestEC2Client(t, h)

	out, err := client.DescribePrincipalIdFormat(t.Context(), &ec2sdk.DescribePrincipalIdFormatInput{
		Resources: []string{"instance"},
	})
	require.NoError(t, err)
	require.Len(t, out.Principals, 1)

	resources := make([]string, 0, len(out.Principals[0].Statuses))
	for _, s := range out.Principals[0].Statuses {
		resources = append(resources, aws.ToString(s.Resource))
	}

	assert.Equal(t, []string{"instance"}, resources,
		"Resource filter ignored -- expected only \"instance\", got %v", resources)
}

// ---- Bug 2: DescribeIamInstanceProfileAssociations ----
//
// handleDescribeIamInstanceProfileAssociations used to unconditionally read
// Filter.1.Value.1 as the instance-id filter value BEFORE checking whether
// Filter.1.Name was actually "instance-id"
// (DescribeIamInstanceProfileAssociationsInput.Filters documents only
// "instance-id" and "state", api_op_DescribeIamInstanceProfileAssociations.go).
// A lone "state" filter sent as Filter.1 was misread as an instance-id
// filter matching no real instance, so every association was silently
// dropped.
func TestDescribeIamInstanceProfileAssociations_StateFilter_RealClient(t *testing.T) {
	t.Parallel()

	h := ec2.NewHandler(ec2.NewInMemoryBackend("000000000000", "us-east-1"))
	client := newTestEC2Client(t, h)

	for range 2 {
		instOut, err := client.RunInstances(t.Context(), &ec2sdk.RunInstancesInput{
			ImageId:      aws.String("ami-sweep41a"),
			InstanceType: types.InstanceTypeT3Micro,
			MinCount:     aws.Int32(1),
			MaxCount:     aws.Int32(1),
		})
		require.NoError(t, err)
		require.Len(t, instOut.Instances, 1)

		_, err = client.AssociateIamInstanceProfile(t.Context(), &ec2sdk.AssociateIamInstanceProfileInput{
			InstanceId: instOut.Instances[0].InstanceId,
			IamInstanceProfile: &types.IamInstanceProfileSpecification{
				Arn: aws.String("arn:aws:iam::000000000000:instance-profile/sweep41a"),
			},
		})
		require.NoError(t, err)
	}

	out, err := client.DescribeIamInstanceProfileAssociations(
		t.Context(),
		&ec2sdk.DescribeIamInstanceProfileAssociationsInput{
			Filters: []types.Filter{
				{Name: aws.String("state"), Values: []string{"associated"}},
			},
		},
	)
	require.NoError(t, err)
	assert.Len(t, out.IamInstanceProfileAssociations, 2,
		"a lone \"state\" filter was misread as an instance-id filter, dropping every association")
}

// ---- Bug 3: DescribeLaunchTemplates ----
//
// handleDescribeLaunchTemplates used to only ever read LaunchTemplateName.N,
// silently ignoring LaunchTemplateId.N even though
// awsEc2query_serializeOpDocumentDescribeLaunchTemplatesInput FlatKeys both
// "LaunchTemplateId" and "LaunchTemplateName" -- a client filtering by
// specific template IDs got every template back unfiltered.
func TestDescribeLaunchTemplates_LaunchTemplateIds_RealClient(t *testing.T) {
	t.Parallel()

	h := ec2.NewHandler(ec2.NewInMemoryBackend("000000000000", "us-east-1"))
	client := newTestEC2Client(t, h)

	lt1, err := client.CreateLaunchTemplate(t.Context(), &ec2sdk.CreateLaunchTemplateInput{
		LaunchTemplateName: aws.String("sweep41-lt1"),
		LaunchTemplateData: &types.RequestLaunchTemplateData{ImageId: aws.String("ami-sweep41b")},
	})
	require.NoError(t, err)

	_, err = client.CreateLaunchTemplate(t.Context(), &ec2sdk.CreateLaunchTemplateInput{
		LaunchTemplateName: aws.String("sweep41-lt2"),
		LaunchTemplateData: &types.RequestLaunchTemplateData{ImageId: aws.String("ami-sweep41c")},
	})
	require.NoError(t, err)

	out, err := client.DescribeLaunchTemplates(t.Context(), &ec2sdk.DescribeLaunchTemplatesInput{
		LaunchTemplateIds: []string{aws.ToString(lt1.LaunchTemplate.LaunchTemplateId)},
	})
	require.NoError(t, err)
	require.Len(t, out.LaunchTemplates, 1,
		"LaunchTemplateIds ignored -- expected exactly the requested template")
	assert.Equal(t, "sweep41-lt1", aws.ToString(out.LaunchTemplates[0].LaunchTemplateName))
}

// ---- Bug 4: DescribeLaunchTemplateVersions ----
//
// handleDescribeLaunchTemplateVersions used to only ever read
// LaunchTemplateId, ignoring LaunchTemplateName (an alternative identifier),
// Versions (FlatKey "LaunchTemplateVersion"), and MinVersion/MaxVersion
// (awsEc2query_serializeOpDocumentDescribeLaunchTemplateVersionsInput). A
// client identifying the template by name alone always got "LaunchTemplateId
// is required"; MinVersion/MaxVersion range requests were silently ignored.
func TestDescribeLaunchTemplateVersions_NameAndVersionRange_RealClient(t *testing.T) {
	t.Parallel()

	h := ec2.NewHandler(ec2.NewInMemoryBackend("000000000000", "us-east-1"))
	client := newTestEC2Client(t, h)

	_, err := client.CreateLaunchTemplate(t.Context(), &ec2sdk.CreateLaunchTemplateInput{
		LaunchTemplateName: aws.String("sweep41-ltv"),
		LaunchTemplateData: &types.RequestLaunchTemplateData{ImageId: aws.String("ami-sweep41d")},
	})
	require.NoError(t, err)

	byName, err := client.DescribeLaunchTemplateVersions(t.Context(), &ec2sdk.DescribeLaunchTemplateVersionsInput{
		LaunchTemplateName: aws.String("sweep41-ltv"),
	})
	require.NoError(t, err,
		"LaunchTemplateName ignored -- LaunchTemplateId was required even though the wire allows either")
	require.Len(t, byName.LaunchTemplateVersions, 1)

	tooHigh, err := client.DescribeLaunchTemplateVersions(t.Context(), &ec2sdk.DescribeLaunchTemplateVersionsInput{
		LaunchTemplateName: aws.String("sweep41-ltv"),
		MinVersion:         aws.String("2"),
	})
	require.NoError(t, err)
	assert.Empty(t, tooHigh.LaunchTemplateVersions,
		"MinVersion ignored -- the only version is 1, which should not satisfy MinVersion=2")
}

// ---- Bug 5: DescribeImageUsageReports ----
//
// handleDescribeImageUsageReports used to ignore its url.Values entirely,
// dropping ReportId.N and ImageId.N even though both are FlatKey lists on
// the wire (awsEc2query_serializeOpDocumentDescribeImageUsageReportsInput).
func TestDescribeImageUsageReports_ReportIdFilter_RealClient(t *testing.T) {
	t.Parallel()

	h := ec2.NewHandler(ec2.NewInMemoryBackend("000000000000", "us-east-1"))
	client := newTestEC2Client(t, h)

	img, err := client.RegisterImage(t.Context(), &ec2sdk.RegisterImageInput{
		Name: aws.String("sweep41-image"),
	})
	require.NoError(t, err)

	resourceTypes := []types.ImageUsageResourceTypeRequest{{ResourceType: aws.String("ec2:Instance")}}

	report1, err := client.CreateImageUsageReport(t.Context(), &ec2sdk.CreateImageUsageReportInput{
		ImageId:       img.ImageId,
		ResourceTypes: resourceTypes,
	})
	require.NoError(t, err)

	_, err = client.CreateImageUsageReport(t.Context(), &ec2sdk.CreateImageUsageReportInput{
		ImageId:       img.ImageId,
		ResourceTypes: resourceTypes,
	})
	require.NoError(t, err)

	out, err := client.DescribeImageUsageReports(t.Context(), &ec2sdk.DescribeImageUsageReportsInput{
		ReportIds: []string{aws.ToString(report1.ReportId)},
	})
	require.NoError(t, err)
	require.Len(t, out.ImageUsageReports, 1, "ReportIds ignored -- expected exactly the requested report")
	assert.Equal(t, aws.ToString(report1.ReportId), aws.ToString(out.ImageUsageReports[0].ReportId))
}

