// ---- Bug 7: DescribeCustomerGateways ----
//
// handleDescribeCustomerGateways used to never read Filters at all
// (awsEc2query_serializeOpDocumentDescribeCustomerGatewaysInput declares
// it), so every customer gateway came back regardless of filter.
func TestDescribeCustomerGateways_Filter_RealClient(t *testing.T) {
	t.Parallel()

	h := ec2.NewHandler(ec2.NewInMemoryBackend("000000000000", "us-east-1"))
	client := newTestEC2Client(t, h)

	cgw1, err := client.CreateCustomerGateway(t.Context(), &ec2sdk.CreateCustomerGatewayInput{
		Type:      types.GatewayTypeIpsec1,
		IpAddress: aws.String("203.0.113.1"),
		BgpAsn:    aws.Int32(65001),
	})
	require.NoError(t, err)

	_, err = client.CreateCustomerGateway(t.Context(), &ec2sdk.CreateCustomerGatewayInput{
		Type:      types.GatewayTypeIpsec1,
		IpAddress: aws.String("203.0.113.2"),
		BgpAsn:    aws.Int32(65002),
	})
	require.NoError(t, err)

	out, err := client.DescribeCustomerGateways(t.Context(), &ec2sdk.DescribeCustomerGatewaysInput{
		Filters: []types.Filter{
			{
				Name:   aws.String("customer-gateway-id"),
				Values: []string{aws.ToString(cgw1.CustomerGateway.CustomerGatewayId)},
			},
		},
	})
	require.NoError(t, err)
	require.Len(t, out.CustomerGateways, 1, "Filters ignored -- expected exactly the requested customer gateway")
	assert.Equal(t, "203.0.113.1", aws.ToString(out.CustomerGateways[0].IpAddress))
}

