// DescribeVpcClassicLink reads the singular VpcId.N correctly
// (awsEc2query_serializeOpDocumentDescribeVpcClassicLinkInput FlatKeys
// "VpcId" -- singular, unlike DescribeVpcClassicLinkDnsSupport below).
func TestDescribeVpcClassicLink_VpcIdFilter_RealClient(t *testing.T) {
	t.Parallel()

	h := ec2.NewHandler(ec2.NewInMemoryBackend("000000000000", "us-east-1"))
	client := newTestEC2Client(t, h)

	vpc1, err := client.CreateVpc(t.Context(), &ec2sdk.CreateVpcInput{CidrBlock: aws.String("10.41.0.0/16")})
	require.NoError(t, err)
	vpc2, err := client.CreateVpc(t.Context(), &ec2sdk.CreateVpcInput{CidrBlock: aws.String("10.42.0.0/16")})
	require.NoError(t, err)

	for _, id := range []*string{vpc1.Vpc.VpcId, vpc2.Vpc.VpcId} {
		_, enableErr := client.EnableVpcClassicLink(t.Context(), &ec2sdk.EnableVpcClassicLinkInput{VpcId: id})
		require.NoError(t, enableErr)
	}

	out, err := client.DescribeVpcClassicLink(t.Context(), &ec2sdk.DescribeVpcClassicLinkInput{
		VpcIds: []string{aws.ToString(vpc1.Vpc.VpcId)},
	})
	require.NoError(t, err)
	require.Len(t, out.Vpcs, 1)
	assert.Equal(t, aws.ToString(vpc1.Vpc.VpcId), aws.ToString(out.Vpcs[0].VpcId))
	assert.True(t, aws.ToBool(out.Vpcs[0].ClassicLinkEnabled))
}

