// DescribeInstanceSqlHaStates reads InstanceId.N correctly
// (awsEc2query_serializeOpDocumentDescribeInstanceSqlHaStatesInput FlatKeys
// "InstanceId").
func TestDescribeInstanceSqlHaStates_InstanceIdFilter_RealClient(t *testing.T) {
	t.Parallel()

	h := ec2.NewHandler(ec2.NewInMemoryBackend("000000000000", "us-east-1"))
	client := newTestEC2Client(t, h)

	instanceIDs := make([]string, 0, 2)

	for range 2 {
		instOut, err := client.RunInstances(t.Context(), &ec2sdk.RunInstancesInput{
			ImageId:      aws.String("ami-sweep41e"),
			InstanceType: types.InstanceTypeT3Micro,
			MinCount:     aws.Int32(1),
			MaxCount:     aws.Int32(1),
		})
		require.NoError(t, err)
		require.Len(t, instOut.Instances, 1)
		instanceIDs = append(instanceIDs, aws.ToString(instOut.Instances[0].InstanceId))
	}

	_, err := client.EnableInstanceSqlHaStandbyDetections(
		t.Context(), &ec2sdk.EnableInstanceSqlHaStandbyDetectionsInput{InstanceIds: instanceIDs},
	)
	require.NoError(t, err)

	out, err := client.DescribeInstanceSqlHaStates(t.Context(), &ec2sdk.DescribeInstanceSqlHaStatesInput{
		InstanceIds: []string{instanceIDs[0]},
	})
	require.NoError(t, err)
	require.Len(t, out.Instances, 1, "InstanceIds ignored -- expected exactly the requested instance")
	assert.Equal(t, instanceIDs[0], aws.ToString(out.Instances[0].InstanceId))
}
